/* The tables of M32 · Inventory and assets. */

export const inventoryCategories = defineTable(
  'inventory_categories',
  { module: 'M32', scope: 'org' },
  {
    ...baseColumns,
    name: text().notNull(),
    kind: enumText(inventoryCategoryKinds).notNull(),
    parentId: uuid().references((): AnyPgColumn => inventoryCategories.id),
  },
  (t) => [uniqueIndex('inventory_categories_name_uq').on(t.orgId, t.name).where(live(t))],
);

export const inventoryItems = defineTable(
  'inventory_items',
  { module: 'M32', scope: 'org' },
  {
    ...baseColumns,
    /** from the `inventory_item` sequence */
    sku: text().notNull(),
    name: text().notNull(),
    nameUr: text(),
    categoryId: uuid()
      .references((): AnyPgColumn => inventoryCategories.id)
      .notNull(),
    /** "pcs", "ream", "box", "kg", "litre" */
    unit: text().notNull(),
    barcode: text(),
    /** groups sizes of one uniform */
    variantGroup: text(),
    /** "Size 32" */
    variantLabel: text(),
    reorderLevel: decimal(12, 3).notNull().default(0),
    reorderQuantity: decimal(12, 3).notNull().default(0),
    /** weighted average, maintained by movements */
    averageCost: paisa().notNull().default(0),
    lastCost: paisa().notNull().default(0),
    /** can be sold in the shop */
    isSellable: boolean().notNull().default(false),
    isActive: boolean().notNull().default(true),
  },
  (t) => [
    nonNegative('inventory_items', t.averageCost),
    nonNegative('inventory_items', t.lastCost),
    uniqueIndex('inventory_items_sku_uq').on(t.orgId, t.sku).where(live(t)),
    uniqueIndex('inventory_items_barcode_uq')
      .on(t.orgId, t.barcode)
      .where(sql`${t.deletedAt} is null and ${t.barcode} is not null`),
    index('inventory_items_name_trgm').using('gin', sql`${t.name} gin_trgm_ops`),
    index('inventory_items_category_idx').on(t.orgId, t.categoryId),
  ],
);

