/** The quantity of an item in a store. Kept in step with movements inside the same transaction. */
export const stockLevels = defineTable(
  'stock_levels',
  { module: 'M32', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    warehouseId: uuid()
      .references((): AnyPgColumn => warehouses.id)
      .notNull(),
    itemId: uuid()
      .references((): AnyPgColumn => inventoryItems.id)
      .notNull(),
    quantity: decimal(12, 3).notNull().default(0),
    value: paisa().notNull().default(0),
  },
  (t) => [
    nonNegative('stock_levels', t.quantity),
    nonNegative('stock_levels', t.value),
    uniqueIndex('stock_levels_warehouse_item_uq').on(t.warehouseId, t.itemId).where(live(t)),
  ],
);

export const stockMovements = defineTable(
  'stock_movements',
  { module: 'M32', scope: 'branch', appendOnly: true, staff: 'append' },
  {
    ...appendColumns,
    branchId: branchIdColumn(),
    /** from the `stock_movement` sequence */
    movementNo: text().notNull(),
    warehouseId: uuid()
      .references((): AnyPgColumn => warehouses.id)
      .notNull(),
    itemId: uuid()
      .references((): AnyPgColumn => inventoryItems.id)
      .notNull(),
    kind: enumText(stockMovementKinds).notNull(),
    /** signed: into the store is positive */
    quantity: decimal(12, 3).notNull(),
    unitCost: paisa().notNull(),
    /** `quantity × unit_cost` */
    value: paisa().notNull(),
    balanceAfter: decimal(12, 3).notNull(),
    movedOn: dateStr().notNull(),
    /** `goods_receipt`, `issue_request`, `stock_transfer`, `stock_count`, `shop_sale`, `manual` */
    sourceType: text().notNull(),
    sourceId: uuid(),
    /** who consumed it */
    departmentId: uuid().references((): AnyPgColumn => departments.id),
    issuedToStaffId: uuid().references((): AnyPgColumn => staff.id),
    costCenterId: uuid().references((): AnyPgColumn => costCenters.id),
    note: text(),
  },
  (t) => [
    nonNegative('stock_movements', t.unitCost),
    uniqueIndex('stock_movements_source_type_source_item_kind_uq')
      .on(t.sourceType, t.sourceId, t.itemId, t.kind)
      .where(sql`${t.sourceId} is not null`),
    index('stock_movements_warehouse_item_moved_on_idx').on(
      t.orgId,
      t.warehouseId,
      t.itemId,
      t.movedOn,
    ),
  ],
);

