export const stockTransfers = defineTable(
  'stock_transfers',
  { module: 'M32', scope: 'org' },
  {
    ...baseColumns,
    /** from the `stock_transfer` sequence */
    transferNo: text().notNull(),
    fromWarehouseId: uuid()
      .references((): AnyPgColumn => warehouses.id)
      .notNull(),
    /** different from the source */
    toWarehouseId: uuid()
      .references((): AnyPgColumn => warehouses.id)
      .notNull(),
    sentOn: dateStr(),
    receivedOn: dateStr(),
    status: enumText(stockTransferStatuses).notNull().default('draft'),
    /** `{ itemId, quantitySent, quantityReceived? }[]` */
    lines: jsonb().notNull(),
    note: text(),
  },
  (t) => [
    check(
      'stock_transfers_to_warehouse_id_differs',
      sql`${t.toWarehouseId} <> ${t.fromWarehouseId}`,
    ),
  ],
);

