export const stockCountLines = defineTable(
  'stock_count_lines',
  { module: 'M32', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    countId: uuid()
      .references((): AnyPgColumn => stockCounts.id)
      .notNull(),
    itemId: uuid()
      .references((): AnyPgColumn => inventoryItems.id)
      .notNull(),
    /** frozen when counting starts */
    systemQuantity: decimal(12, 3).notNull(),
    countedQuantity: decimal(12, 3),
    /** required when they differ */
    reason: text(),
  },
  (t) => [
    check(
      'stock_count_lines_reason_needed',
      sql`${t.countedQuantity} is null or ${t.countedQuantity} = ${t.systemQuantity} or ${t.reason} is not null`,
    ),
    uniqueIndex('stock_count_lines_count_item_uq').on(t.countId, t.itemId).where(live(t)),
  ],
);

