export const assets = defineTable(
  'assets',
  { module: 'M32', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** from the `asset` sequence; printed on its tag */
    assetNo: text().notNull(),
    name: text().notNull(),
    categoryId: uuid()
      .references((): AnyPgColumn => assetCategories.id)
      .notNull(),
    description: text(),
    serialNo: text(),
    makeModel: text(),
    purchasedOn: dateStr(),
    cost: paisa().notNull().default(0),
    salvageValue: paisa().notNull().default(0),
    vendorId: uuid().references((): AnyPgColumn => vendors.id),
    vendorBillId: uuid().references((): AnyPgColumn => vendorBills.id),
    roomId: uuid().references((): AnyPgColumn => rooms.id),
    custodianStaffId: uuid().references((): AnyPgColumn => staff.id),
    condition: enumText(assetConditions).notNull().default('good'),
    status: enumText(assetStatuses).notNull().default('in_use'),
    warrantyUntil: dateStr(),
    depreciationStartsOn: dateStr(),
    accumulatedDepreciation: paisa().notNull().default(0),
    /** generated: `cost - accumulated_depreciation` */
    bookValue: paisa().generatedAlwaysAs(
      (): SQL => sql`${assets.cost} - ${assets.accumulatedDepreciation}`,
    ),
    disposedOn: dateStr(),
    disposalAmount: paisa(),
    disposalReason: text(),
  },
  (t) => [
    nonNegative('assets', t.cost),
    nonNegative('assets', t.salvageValue),
    nonNegative('assets', t.accumulatedDepreciation),
    nonNegative('assets', t.disposalAmount),
    uniqueIndex('assets_asset_no_uq').on(t.orgId, t.assetNo).where(live(t)),
    index('assets_branch_status_idx').on(t.orgId, t.branchId, t.status),
    index('assets_custodian_staff_idx').on(t.orgId, t.custodianStaffId),
    index('assets_room_idx').on(t.orgId, t.roomId),
  ],
);

